question_text:
What is the output of the following code?

int x = 10;
if(x > 5)
    cout << "Yes";
else
    cout << "No";

What is the output of the following code?

int x = 5;
if(x == 5)
    cout << "Equal";

What is the output of the following code?

int x = 0;
if(x)
    cout << "True";
else
    cout << "False";

What is the output of the following code?

int a = 10;
int b = 20;

if(a < b)
    cout << "A";
else
    cout << "B";

What is the output of the following code?

int n = 7;

if(n % 2 == 0)
    cout << "Even";
else
    cout << "Odd";

What is the output?

for(int i = 1; i <= 3; i++)
    cout << i;

What is the output?

int i = 1;
while(i <= 3) {
    cout << i;
    i++;
}

What is the output?

int i = 5;
do {
    cout << i;
} while(i < 3);

What is the output?

for(int i = 1; i <= 3; i++) {
    if(i == 2)
        continue;
    cout << i;
}

What is the output?

for(int i = 1; i <= 5; i++) {
    if(i == 3)
        break;
    cout << i;
}

How many times will the inner statement execute?

for(int i = 0; i < 2; i++) {
    for(int j = 0; j < 3; j++) {
        cout << "*";
    }
}

What is the output?

int sum = 0;

for(int i = 1; i <= 3; i++) {
    sum += i;
}

cout << sum;

What is the output?

int arr[3] = {10, 20, 30};
cout << arr[1];

What is the output?

string s = "Hello";
cout << s.length();

What is the output?

string s = "Coding";
cout << s[0];

What is the output?

int arr[4] = {1, 2, 3, 4};
cout << arr[0] + arr[3];

What is the output?

string s = "Hello";
s += " World";
cout << s;

What is the output?

int add(int a, int b) {
    return a + b;
}

int main() {
    cout << add(2, 3);
}

What is the output?

void show() {
    cout << "Hello";
}

int main() {
    show();
}

What is the output?

int square(int x) {
    return x * x;
}

int main() {
    cout << square(4);
}

What is the output?

int x = 10;
int *p = &x;
cout << *p;

What is the output?

int x = 5;
int *p = &x;
*p = 20;
cout << x;
